   "id": "P2",
   "product": "协作宝",
   "step": 2,
   "title": "会议室列表看不出是否空闲",
   "severity": "高",
   "evidence": "选了房间才发现没有空闲时段"
  },
  {
   "id": "P3",
   "product": "协作宝",
   "step": 6,
   "title": "超出容量才提示",
   "severity": "中",
   "evidence": "要回到第 2 步重选会议室"
  },
  {
   "id": "P4",
   "product": "协作宝",
   "step": 5,
   "title": "会议主题必填",
   "severity": "低",
   "evidence": "主题多为“会议”“讨论”"
  }
