  {
   "id": "A1",
   "title": "先问时间、时长和人数",
   "detail": "根据需求直接列出空闲会议室",
   "basis": [
    "链工第 1、2 步",
    "P1",
    "P2"
   ]
  },
  {
   "id": "A2",
   "title": "人数作为筛选条件",
   "detail": "在找会议室时就排除容量不够的",
   "basis": [
    "链工第 1 步",
    "P3"
   ]
  },
  {
   "id": "A3",
   "title": "主题改为选填",
   "detail": "留空时用发起人姓名代替",
   "basis": [
    "P4"
   ]
  }
 ]
}

